import json,hashlib,sys,string
def dump(p,x): open(p,"w").write(json.dumps(x,sort_keys=True,separators=(",",":"))+"\n")
def main(s):
 if s=="scan": dump("docs.json",[{"file":n,"bytes":len(open(n,"rb").read())} for n in open("files.txt").read().splitlines()])
 elif s=="index":
  d={}
  for x in json.load(open("docs.json")):
   for w in open(x["file"]).read().lower().split():
    word=w.strip(string.punctuation)
    if word: d.setdefault(word,set()).add(x["file"])
  dump("index.json",{k:sorted(v) for k,v in d.items()})
 elif s=="manifest": dump("manifest.json",{"sha256":{p:hashlib.sha256(open(p,"rb").read()).hexdigest() for p in ("docs.json","index.json")},"document_count":len(json.load(open("docs.json")))})
if __name__=="__main__": main(sys.argv[1])
